/* ============================================================================
   002 — Catálogo completo de municipios de Colombia (DIVIPOLA / DANE)
   ----------------------------------------------------------------------------
   conf_ciudades traía solo 240 municipios (Bogotá, Boyacá y Cundinamarca).
   El cliente reportó que en los desplegables "solo carga Colombia, un
   departamento y Paipa" -- ese era el motivo.

   Esta migración inserta los 880 que faltaban, hasta completar los 1.120
   (33 departamentos). Fuente: DIVIPOLA del DANE, con los nombres acentuados
   cruzados contra un segundo conjunto de datos independiente.

   Re-ejecutable: cada fila se inserta solo si su código DANE no existe ya.
   Ya aplicada en Paipa el 2026-08-11 (880 insertados, 0 errores).
   ============================================================================ */

/* Normaliza el uso de mayúsculas de los tres grupos que ya existían, para que
   no convivan "BOGOTÁ D.C." y "Bogotá D.C." en el mismo desplegable. */
UPDATE dbo.conf_ciudades SET ciu_Departamento = 'Bogotá D.C.'  WHERE ciu_Departamento = 'BOGOTÁ D.C.';
UPDATE dbo.conf_ciudades SET ciu_Departamento = 'Cundinamarca' WHERE ciu_Departamento = 'CUNDINAMARCA';
GO

